using System.IO;
using System.IO.Compression;
using System.Xml;
using System.Xml.Linq;
namespace Ansary;
public sealed record FootnoteData(string Id,string Label,string Text);
public sealed record FootnoteReference(int Offset,FootnoteData Note);
public sealed class FootnoteMap {public Dictionary<int,List<FootnoteReference>> References{get;}=new();}
public sealed class ReadingOptions {public double TextSize{get;set;}=18;public double NoteSize{get;set;}=16;public double OutlineSize{get;set;}=14;public double LineFactor{get;set;}=1.5;public double ParagraphGap{get;set;}=6;public string FontName{get;set;}="Segoe UI";public bool BottomNotes{get;set;}=true;public void Normalize(){TextSize=Clamp(TextSize,10,48,18);NoteSize=Clamp(NoteSize,10,40,16);OutlineSize=Clamp(OutlineSize,10,32,14);LineFactor=Clamp(LineFactor,1.1,2.5,1.5);ParagraphGap=Clamp(ParagraphGap,0,30,6);if(string.IsNullOrWhiteSpace(FontName))FontName="Segoe UI";}static double Clamp(double n,double min,double max,double fallback)=>double.IsFinite(n)?Math.Clamp(n,min,max):fallback;}
public static class ReadingData {
 static XDocument? Load(ZipArchive zip,string name,long max){var e=zip.GetEntry(name);if(e==null)return null;if(e.Length>max)throw new InvalidDataException("تجاوز محتوى الحواشي حد القراءة الآمنة");using var stream=e.Open();using var reader=XmlReader.Create(stream,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=max});return XDocument.Load(reader);}
 static string Text(XElement p)=>string.Concat(p.Descendants().Select(x=>x.Name.LocalName switch{"t"=>x.Value,"tab"=>"\t","br"=>"\n",_=>""}));
 public static FootnoteMap ReadNotes(string path){using var zip=ZipFile.OpenRead(path);var result=new FootnoteMap();var notes=Load(zip,"word/footnotes.xml",16L*1024*1024);if(notes==null)return result;XNamespace w="http://schemas.openxmlformats.org/wordprocessingml/2006/main";var definitions=new Dictionary<string,string>();foreach(var n in notes.Descendants(w+"footnote")){string? id=(string?)n.Attribute(w+"id"),type=(string?)n.Attribute(w+"type");if(id==null||type!=null&&type!="normal"||id.StartsWith("-"))continue;definitions[id]=string.Join("\n",n.Descendants(w+"p").Select(Text));}var doc=Load(zip,"word/document.xml",32L*1024*1024)??throw new InvalidDataException("ملف DOCX غير صالح");var labels=new Dictionary<string,FootnoteData>();int index=0;foreach(var p in doc.Descendants().Where(x=>x.Name.LocalName=="p")){int offset=0;foreach(var x in p.Descendants()){switch(x.Name.LocalName){case "t":offset+=x.Value.Length;break;case "tab":case "br":offset++;break;case "footnoteReference":string? id=(string?)x.Attribute(w+"id");if(id==null)break;if(!labels.TryGetValue(id,out var note)){note=new FootnoteData(id,(labels.Count+1).ToString(),definitions.GetValueOrDefault(id,"تعذر العثور على نص هذه الحاشية"));labels.Add(id,note);}if(!result.References.TryGetValue(index,out var list))result.References[index]=list=new();list.Add(new FootnoteReference(offset,note));break;}}index++;}return result;}
 public static string CopyRange(string[] paragraphs,int first,int last){int start=Math.Min(first,last),end=Math.Max(first,last);if(start<0||end>=paragraphs.Length)throw new ArgumentOutOfRangeException();return string.Join(Environment.NewLine+Environment.NewLine,paragraphs.Skip(start).Take(end-start+1));}
 public static void Verify(){if(CopyRange(new[]{"A","B","C"},2,0)!=string.Join(Environment.NewLine+Environment.NewLine,new[]{"A","B","C"}))throw new InvalidOperationException("Paragraph range regression");var o=new ReadingOptions{TextSize=999,LineFactor=double.NaN};o.Normalize();if(o.TextSize!=48||o.LineFactor!=1.5)throw new InvalidOperationException("Reading settings regression");string dir=Path.Combine(Path.GetTempPath(),"AnsaryNotes-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string path=Path.Combine(dir,"notes.docx");using(var zip=ZipFile.Open(path,ZipArchiveMode.Create)){void Write(string name,string xml){using var wr=new StreamWriter(zip.CreateEntry(name).Open());wr.Write(xml);}Write("word/document.xml","<w:document xmlns:w='http://schemas.openxmlformats.org/wordprocessingml/2006/main'><w:body><w:p><w:r><w:t>أ</w:t><w:footnoteReference w:id='7'/><w:t>ب</w:t></w:r></w:p></w:body></w:document>");Write("word/footnotes.xml","<w:footnotes xmlns:w='http://schemas.openxmlformats.org/wordprocessingml/2006/main'><w:footnote w:id='0' w:type='separator'><w:p/></w:footnote><w:footnote w:id='7'><w:p><w:r><w:t>نص الحاشية</w:t></w:r></w:p></w:footnote></w:footnotes>");}var note=ReadNotes(path).References[0].Single();if(note.Offset!=1||note.Note.Id!="7"||note.Note.Text!="نص الحاشية"||Core.Read(path)[0]!="أب")throw new InvalidOperationException("Footnote mapping regression");}finally{Directory.Delete(dir,true);}}
}
